#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    fn assert_catalog<T: Copy>(catalog: &[ItemComponentValueCatalogEntry<T>]) {
        let mut constants = HashSet::new();
        let mut names = HashSet::new();
        for (id, entry) in catalog.iter().enumerate() {
            assert_eq!(entry.id, id as i32);
            assert!(constants.insert(entry.constant_name));
            if let Some(name) = entry.serialized_name {
                assert!(names.insert(name));
            }
        }
    }

    #[test]
    fn item_component_value_catalogs_are_complete_contiguous_and_unique() {
        assert_eq!(VANILLA_ITEM_USE_ANIMATIONS.len(), 12);
        assert_eq!(VANILLA_SWING_ANIMATION_TYPES.len(), 3);
        assert_eq!(VANILLA_ITEM_RARITIES.len(), 4);
        assert_eq!(VANILLA_MAP_POST_PROCESSING_VALUES.len(), 2);
        assert_eq!(VANILLA_FIREWORK_EXPLOSION_SHAPES.len(), 5);
        assert_catalog(VANILLA_ITEM_USE_ANIMATIONS);
        assert_catalog(VANILLA_SWING_ANIMATION_TYPES);
        assert_catalog(VANILLA_ITEM_RARITIES);
        assert_catalog(VANILLA_MAP_POST_PROCESSING_VALUES);
        assert_catalog(VANILLA_FIREWORK_EXPLOSION_SHAPES);
    }

    #[test]
    fn item_component_value_catalogs_preserve_ids_names_and_zero_fallback() {
        assert_eq!(ItemUseAnimationSummary::Spear.id(), 11);
        assert_eq!(
            ItemUseAnimationSummary::from_id(12),
            ItemUseAnimationSummary::None
        );
        assert_eq!(ItemUseAnimationSummary::TootHorn.as_str(), "toot_horn");
        assert_eq!(
            SwingAnimationTypeSummary::from_id(2),
            SwingAnimationTypeSummary::Stab
        );
        assert_eq!(
            SwingAnimationTypeSummary::from_id(-1),
            SwingAnimationTypeSummary::None
        );
        assert_eq!(ItemRaritySummary::Rare.as_str(), "rare");
        assert_eq!(ItemRaritySummary::from_id(4), ItemRaritySummary::Common);
        assert_eq!(
            MapPostProcessingSummary::from_id(1),
            MapPostProcessingSummary::Scale
        );
        assert_eq!(
            MapPostProcessingSummary::from_id(2),
            MapPostProcessingSummary::Lock
        );
        assert_eq!(
            FireworkExplosionShapeSummary::from_serialized_name("large_ball"),
            Some(FireworkExplosionShapeSummary::LargeBall)
        );
        assert_eq!(
            FireworkExplosionShapeSummary::from_id(5),
            FireworkExplosionShapeSummary::SmallBall
        );
    }

    #[test]
    fn production_sources_do_not_redeclare_item_component_value_facts() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/item_component_value_types.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                let production = source.split("#[cfg(test)]").next().unwrap_or(&source);
                if production.contains("enum ItemUseAnimationSummary {")
                    || production.contains("enum SwingAnimationTypeSummary {")
                    || production.contains("enum FireworkExplosionShapeSummary {")
                    || production.contains("enum ItemRaritySummary {")
                    || production.contains("enum MapPostProcessingSummary {")
                    || production.contains("fn firework_explosion_shape_name")
                    || production.contains("trait ItemRaritySummaryExt")
                    || production.contains("1 => ItemRaritySummary::Uncommon")
                    || production.contains("1 => SwingAnimationTypeSummary::Whack")
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel item component value owners: {violations:?}"
        );
    }
}
